游游的重组偶数题意重排正整数 $n$ 的数位，使得它变成偶数（不能有前导零）。 思考枚举找到偶数位，特判 $s_0$ 是偶数但 $s_{1}$ 是 ‘0’ 的情况，substr 直接输出即可。 小欧的平面连线题意平面直角坐标系上（除坐标轴上）有 $n$ 个整数点（$n$ 是偶数），将这些点任意两两配对形成线段，线段穿过的坐标轴个数即为这一点对的贡献。求最大的权值和。 思考贪心。直接考虑按象限划分，先将对角象限的点们进行配对。此时未配对的点一定只位于一个象限或两个相邻象限。如果是前者则没有额外贡献了，否则再加上能产生的大小为 1 的贡献们即可。 1234567891011121314151617181920212223242526272829303132333435363738394041424344454647/********************************************************&gt; File Name: e.cpp&gt; Author: zylll&gt; Blog: https://ylzhang.top&gt; Created Time: Mon Oct 27 22:52:47 2025 *******************************************************/#include &lt;bits/stdc++.h&gt;int check(int x, int y) { if (x &gt; 0 &amp;&amp; y &gt; 0) return 1; else if (x &lt; 0 &amp;&amp; y &gt; 0) return 2; else if (x &lt; 0 &amp;&amp; y &lt; 0) return 3; else return 4;}int main() { std::ios::sync_with_stdio(false); std::cin.tie(0); std::cout.tie(0); // freopen(&quot;in&quot;, &quot;r&quot;, stdin); int n, x, y; std::vector&lt;int&gt; part(5, 0); std::cin &gt;&gt; n; for (int i = 1; i &lt;= n; i++) { std::cin &gt;&gt; x &gt;&gt; y; part[check(x, y)]++; } int ans = 0, cnt1 = std::min(part[1], part[3]), cnt2 = std::min(part[2], part[4]); ans += (cnt1 + cnt2) * 2; part[1] -= cnt1; part[3] -= cnt1; part[2] -= cnt2; part[4] -= cnt2; int cnt = 0; std::vector&lt;int&gt; last; for (int i = 1; i &lt;= 4; i++) { if (part[i] != 0) last.push_back(i); } if (last.size() == 2) { ans += std::min(part[last[0]], part[last[1]]); } std::cout &lt;&lt; ans &lt;&lt; &quot;
&quot;; return 0;} 小红的四子棋题意给一个“四子棋”的结局地图，判断输赢还是平局。 思考四个方向直接枚举即可。 123456789101112131415161718192021222324252627282930313233343536373839404142434445464748495051525354555657585960616263646566676869707172737475767778798081828384858687888990919293949596979899100101102103104105106107108109110111112113114115116117118119120121122123124125126/********************************************************&gt; File Name: f.cpp&gt; Author: zylll&gt; Blog: https://ylzhang.top&gt; Created Time: Mon Oct 27 23:10:47 2025 *******************************************************/#include &lt;bits/stdc++.h&gt;const int MAXN = 105;const int ASCII_SIZE = 200;int n, m;std::vector&lt;std::string&gt; a, b;int vnum[ASCII_SIZE][MAXN], hnum[ASCII_SIZE][MAXN];bool check_v(char c) { for (int i = 1; i &lt;= n; i++) { if (vnum[c][i] &lt; 4) continue; for (int j = 1; j + 3 &lt;= m; j++) { if (a[i][j] == c &amp;&amp; a[i][j + 1] == c &amp;&amp; a[i][j + 2] == c &amp;&amp; a[i][j + 3] == c) { return 1; } } } return 0;}bool check_h(char c) { for (int j = 1; j &lt;= m; j++) { if (hnum[c][j] &lt; 4) continue; for (int i = 0; i + 3 &lt; n; i++) { if (b[j][i] == c &amp;&amp; b[j][i + 1] == c &amp;&amp; b[j][i + 2] == c &amp;&amp; b[j][i + 3] == c) { return 1; } } } return 0;}bool check_vh(char c) { int delx = 1, dely = 1; for (int j = 1; j &lt;= m; j++) { int sx = 1, sy = j, cnt = 0; while (sx &lt;= n &amp;&amp; sy &lt;= m) { if (a[sx][sy] == c) cnt++; else cnt = 0; sx += delx; sy += dely; if (cnt == 4) return 1; } } for (int i = 2; i &lt;= n; i++) { int sx = i, sy = 1, cnt = 0; while (sx &lt;= n &amp;&amp; sy &lt;= m) { if (a[sx][sy] == c) cnt++; else cnt = 0; sx += delx; sy += dely; if (cnt == 4) return 1; } } dely = -1; for (int j = 1; j &lt;= m; j++) { int sx = 1, sy = j, cnt = 0; while (sx &lt;= n &amp;&amp; sy &gt; 0) { if (a[sx][sy] == c) cnt++; else cnt = 0; sx += delx; sy += dely; if (cnt == 4) return 1; } } for (int i = 2; i &lt;= n; i++) { int sx = i, sy = m, cnt = 0; while (sx &lt;= n &amp;&amp; sy &gt; 0) { if (a[sx][sy] == c) cnt++; else cnt = 0; sx += delx; sy += dely; if (cnt == 4) return 1; } } return 0;}int main() { std::ios::sync_with_stdio(false); std::cin.tie(0); std::cout.tie(0); // freopen(&quot;in&quot;, &quot;r&quot;, stdin); std::cin &gt;&gt; n &gt;&gt; m; a.resize(n + 1); for (int i = 1; i &lt;= n; i++) { a[i].resize(m + 1); for (int j = 1; j &lt;= m; j++) { std::cin &gt;&gt; a[i][j]; vnum[a[i][j]][i]++; hnum[a[i][j]][j]++; } } b.resize(m + 1); for (int j = 1; j &lt;= m; j++) { for (int i = 1; i &lt;= n; i++) { b[j] += a[i][j]; } } if (check_v('r') || check_h('r') || check_vh('r')) std::cout &lt;&lt; &quot;kou&quot; &lt;&lt; &quot;
